function StatusPill({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "neutral" | "teal" | "amber" | "coral" | "rose" | "ink" }) {
  const tones = {
    neutral: "bg-[#e9e8e1] text-[#53636b]",
    teal: "bg-[#d9f5ef] text-[#15786e]",
    amber: "bg-[#f8edcf] text-[#916b17]",
    coral: "bg-[#fbe2d9] text-[#a34c37]",
    rose: "bg-[#f8dfe1] text-[#a03c4a]",
    ink: "bg-[#e4e9ea] text-[#22323a]",
  };
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[10px] font-semibold uppercase tracking-[.08em] ${tones[tone]}`}>{children}</span>;
}

function RiskPill({ level }: { level: Transaction["level"] }) {
  const map = { low: ["LOW", "teal"], medium: ["MEDIUM", "amber"], high: ["HIGH", "coral"], critical: ["CRITICAL", "rose"] } as const;
  const [label, tone] = map[level];
  return <StatusPill tone={tone}>{label}</StatusPill>;
}

function DecisionPill({ decision }: { decision: Transaction["decision"] }) {
  const tone = decision === "approve" ? "teal" : decision === "block" ? "rose" : "amber";
  return <StatusPill tone={tone}>{decision}</StatusPill>;
}

